def prepare_grant_uri(uri, client_id, response_type, redirect_uri=None,
    scope=None, state=None, code_challenge=None, code_challenge_method=
    'plain', **kwargs):
    """Prepare the authorization grant request URI.

    The client constructs the request URI by adding grant parameters to the
    query component of the redirection URI using the
    ``application/x-www-form-urlencoded`` format.
    """
    params = [
        ('client_id', client_id),
        ('response_type', response_type),
    ]

    if redirect_uri:
        params.append(('redirect_uri', redirect_uri))

    if scope:
        params.append(('scope', list_to_scope(scope)))

    if state:
        params.append(('state', state))

    if code_challenge:
        params.append(('code_challenge', code_challenge))
        if code_challenge_method:
            params.append(('code_challenge_method', code_challenge_method))

    for k, v in kwargs.items():
        if v:
            params.append((str(k), v))

    return add_params_to_uri(uri, params)
